+             * the last released version for docs. */
+            "\\{version\\}",
+            Version.fromString(VersionProperties.getElasticsearch()).toString(),
+            "\\{version_qualified\\}",
+            VersionProperties.getElasticsearch(),
+            "\\{lucene_version\\}",
+            VersionProperties.getLucene().replaceAll("-snapshot-\\w+$", ""),
+            "\\{build_flavor\\}",
+            distribution,
+            "\\{build_type\\}",
